from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

import heapq


def _route(minimum_duration, exact_coupons):
    def solve(data):
        required = data.get("required", [])
        full = (1 << len(required)) - 1
        initial_mask = 0
        for i, node in enumerate(required):
            if node == data["source"]:
                initial_mask |= 1 << i

        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_state = (data["source"], initial_mask, 0)
        best = {start_state: data["start"]}
        queue = [(data["start"], data["source"], initial_mask, 0)]
        while queue:
            arrival, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if best.get(state) != arrival:
                continue
            if (node == data["target"] and mask == full and
                    (not exact_coupons or used == data["coupons"])):
                return {"arrival": arrival}

            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], used)]
                if used < data["coupons"]:
                    duration = max(minimum_duration,
                                   edge["duration"] - edge.get("discount", 0))
                    options.append((duration, used + 1))
                for duration, next_used in options:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask
                    for i, required_node in enumerate(required):
                        if next_node == required_node:
                            next_mask |= 1 << i
                    next_state = (next_node, next_mask, next_used)
                    if next_time < best.get(next_state, float("inf")):
                        best[next_state] = next_time
                        heapq.heappush(queue, (next_time, next_node,
                                              next_mask, next_used))
        return {"arrival": None}
    return solve


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    half_up = data["rounding"] == "half_up"

    def rounded(numerator):
        return (numerator + 5000) // 10000 if half_up else numerator // 10000

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = (event.get("account", "default") + "|" +
               event.get("currency", "USD"))
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _resolver(data):
    packages = data["packages"]
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    names = sorted(packages, reverse=True)
    best_vector = None
    best_installation = None

    def cyclic(graph):
        finished = set()
        active = set()

        def visit(name):
            if name in active:
                return True
            if name in finished:
                return False
            active.add(name)
            for other in graph.get(name, ()):
                if visit(other):
                    return True
            active.remove(name)
            finished.add(name)
            return False

        return any(visit(name) for name in graph)

    def search(constraints, chosen, graph):
        nonlocal best_vector, best_installation
        pending = [name for name in constraints if name not in chosen]
        if not pending:
            vector = tuple(chosen.get(name, -1) for name in names)
            if best_vector is None or vector < best_vector:
                best_vector = vector
                best_installation = dict(chosen)
            return

        name = min(pending)
        low, high = constraints[name]
        rows = [row for row in packages.get(name, [])
                if low <= row["version"] <= high
                and row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        for row in rows:
            version = row["version"]
            next_chosen = dict(chosen)
            next_chosen[name] = version
            next_constraints = dict(constraints)
            next_graph = {key: list(value) for key, value in graph.items()}
            dependencies = [dep for dep in row.get("deps", [])
                            if not dep.get("feature") or dep["feature"] in features]
            valid = True
            next_graph[name] = []
            for dep in dependencies:
                other = dep["name"]
                next_graph[name].append(other)
                lo, hi = dep["min"], dep["max"]
                if other in next_constraints:
                    old_lo, old_hi = next_constraints[other]
                    lo, hi = max(lo, old_lo), min(hi, old_hi)
                if lo > hi:
                    valid = False
                    break
                next_constraints[other] = (lo, hi)
                if other in next_chosen and not lo <= next_chosen[other] <= hi:
                    valid = False
                    break
            if valid and not cyclic(next_graph):
                search(next_constraints, next_chosen, next_graph)

    constraints = {}
    for name, bounds in data["roots"].items():
        if name in constraints:
            low, high = constraints[name]
            constraints[name] = (max(low, bounds[0]), min(high, bounds[1]))
        else:
            constraints[name] = (bounds[0], bounds[1])
    if all(low <= high for low, high in constraints.values()):
        search(constraints, {}, {})
    if best_installation is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_installation}


def _scheduler(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    if not mandatory.issubset({job["id"] for job in jobs}):
        return {"error": "impossible"}

    def valid(selection):
        ids = {job["id"] for job in selection}
        if not mandatory.issubset(ids):
            return False
        counts = {}
        for job in selection:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        for group, bounds in quotas.items():
            count = counts.get(group, 0)
            if not bounds[0] <= count <= bounds[1]:
                return False
        ordered = sorted(selection, key=lambda job: (job["start"], job["end"]))
        return all(ordered[i - 1]["end"] <= ordered[i]["start"]
                   for i in range(1, len(ordered)))

    def enumerate_selections(index, selection):
        nonlocal best_value, best_ids
        if len(selection) == k:
            if valid(selection):
                value = sum(job["value"] for job in selection)
                ids = sorted(job["id"] for job in selection)
                if (best_value is None or value > best_value or
                        (value == best_value and ids < best_ids)):
                    best_value, best_ids = value, ids
            return
        if index == len(jobs) or len(selection) + len(jobs) - index < k:
            return
        enumerate_selections(index + 1, selection)
        enumerate_selections(index + 1, selection + [jobs[index]])

    enumerate_selections(0, [])
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


SOLVERS = {
    "component_01": _route(2, False),
    "component_02": _route(2, True),
    "component_03": _route(1, False),
    "component_04": _route(1, True),
    "component_05": _route(2, False),
    "component_06": _ledger,
    "component_07": _resolver,
    "component_08": _scheduler,
}
